async function fakeFetch(path, tok) {
  await null;
  return tok === "new" ? { status: 200, body: { path } } : { status: 401, body: null };
}
function refresh() {
  // share one refresh promise between parallel callers
  if (!refreshing) refreshing = (async () => { refreshCount++; await null; token = "new"; })()
    .finally(() => { refreshing = null; });
