// A tiny store with subscribe: selectors limit who re-renders. Time O(subscribers), space O(n).
function createStore(initial) {
  let state = initial; const subs = [];
  return {
    get: () => state,
    set(patch) { state = { ...state, ...patch }; subs.forEach(s => s(state)); },
    subscribe(selector, cb) { // call cb only when the selected slice changes
      let last = selector(state);
      subs.push(s => { const next = selector(s); if (next !== last) { last = next; cb(next); } });
    },
  };
