// Server-state cache: staleTime, dedupe of in-flight requests, invalidation per key.
// Time O(1) per lookup, space O(keys).
const cache = new Map(); let fetches = 0;
const STALE = 50;
async function query(key, fetcher, now) {
  const e = cache.get(key);
  if (e && e.promise) return e.promise;                       // dedupe in-flight
  if (e && now - e.at < STALE) return e.data;                 // fresh: no network
  const promise = fetcher().then(data => { cache.set(key, { data, at: now }); return data; });
  cache.set(key, { ...(e || {}), promise });
  return promise;
}
