  console.log("two parallel callers, fetches =", fetches, JSON.stringify(a), JSON.stringify(b));
  await query("user:1", api(1), 10); console.log("within staleTime, fetches =", fetches);
  await query("user:1", api(1), 100); console.log("after staleTime, fetches =", fetches);
  invalidate("user:1"); await query("user:1", api(1), 101); console.log("after invalidate, fetches =", fetches);
