// Search + paging on the client: filter first, then slice. Debounce the input.
// Time O(n) per query, space O(page).
const users = Array.from({ length: 23 }, (_, i) => ({ id: i + 1, name: (i % 2 ? "Anna" : "Bob") + i }));
function list({ q = "", page = 1, size = 5 }) {
  const hits = users.filter(u => u.name.toLowerCase().includes(q.toLowerCase()));
  const pages = Math.max(1, Math.ceil(hits.length / size));
  const p = Math.min(Math.max(page, 1), pages); // clamp page
  return { total: hits.length, page: p, pages, rows: hits.slice((p - 1) * size, p * size).map(u => u.name) };
}
