// Dependency injection: a container resolves services by token; tests override providers.
// Time O(1) per resolve, space O(providers).
class Injector {
  constructor(providers, parent) { this.p = new Map(providers); this.cache = new Map(); this.parent = parent; }
  get(token) {
    if (this.cache.has(token)) return this.cache.get(token);  // singleton per injector
    if (!this.p.has(token)) {
      if (this.parent) return this.parent.get(token);
      throw new Error("No provider for " + token);              // like NullInjectorError
    }
    const v = this.p.get(token)(this); this.cache.set(token, v); return v;
  }
}
