// Cross-field validator: a group-level rule sees both fields. Time O(fields), space O(errors).
const fieldRules = {
  password: v => (v.length >= 8 ? null : "min 8 characters"),
  confirm: v => (v ? null : "required"),
};
const groupRules = [g => (g.password === g.confirm ? null : "passwords do not match")];
function validate(form) {
  const errors = {};
  for (const [f, rule] of Object.entries(fieldRules)) { const e = rule(form[f]); if (e) errors[f] = e; }
  const groupErrors = groupRules.map(r => r(form)).filter(Boolean);
  return { valid: !Object.keys(errors).length && !groupErrors.length, errors, groupErrors };
}
