// Route guards: run in order, first failure redirects. Time O(guards), space O(1).
const session = { user: { name: "Ada", roles: ["user"] } };
const authGuard = () => (session.user ? true : "/login");
const adminGuard = () => (session.user && session.user.roles.includes("admin") ? true : "/forbidden");
const routes = [
  { path: "/home", guards: [] },
  { path: "/profile", guards: [authGuard] },
  { path: "/admin", guards: [authGuard, adminGuard] },
];
function navigate(path) {
  const route = routes.find(r => r.path === path);
  if (!route) return path + " -> 404";
  for (const g of route.guards) { const r = g(); if (r !== true) return path + " -> redirect " + r; }
  return path + " -> allowed";
}
["/home", "/profile", "/admin", "/nope"].forEach(p => console.log(navigate(p)));
session.user = null;
console.log("after logout:", navigate("/profile"));
