// Signals: writable value, computed that tracks dependencies, effect that reruns.
// Time O(subscribers) per write, space O(deps).
let active = null;
function signal(v) {
  const subs = new Set();
  const s = () => { if (active) subs.add(active); return v; };    // read registers dependency
  s.set = nv => { if (nv !== v) { v = nv; [...subs].forEach(f => f()); } };
  return s;
}
function effect(fn) { const run = () => { active = run; fn(); active = null; }; run(); }
function computed(fn) {
  const out = signal(undefined);
  effect(() => out.set(fn()));
  return out;
}
const price = signal(10), qty = signal(2);
const total = computed(() => price() * qty());        // derived, never set by hand
effect(() => console.log("total is", total()));
qty.set(3);
price.set(20);
qty.set(3); // same value: no update, no log
console.log("final total:", total());

// RxJS ideas without the library: map, switchMap (cancel previous), catchError placement.
// Time O(events), space O(1).
const sleep = ms => new Promise(r => setTimeout(r, ms));
// switchMap: only the latest inner request's result is used
function switchMapLatest(fn) {
  let id = 0;
  return async input => { const mine = ++id; const out = await fn(input); return mine === id ? out : undefined; };
}
const search = switchMapLatest(async q => { await sleep(q === "a" ? 30 : 5); return "results for " + q; });
