// Change detection: Default checks every component; OnPush only when inputs change or marked.
// Time O(components checked), space O(1).
function makeComp(name, onPush) {
  return { name, onPush, dirty: true, checks: 0, input: null };
}
function setInput(c, v) { if (c.input !== v) { c.input = v; c.dirty = true; } } // new reference => dirty
function tick(comps) {
  for (const c of comps) {
    if (c.onPush && !c.dirty) continue;     // skipped subtree
    c.checks++; c.dirty = false;
  }
}
const def = makeComp("Default", false), push = makeComp("OnPush", true);
const user = { name: "Ada" };
setInput(def, user); setInput(push, user);
for (let i = 0; i < 5; i++) tick([def, push]);       // 5 events, nothing changed
console.log("5 ticks, no input change   ->", def.name, def.checks, push.name, push.checks);
user.name = "Grace";                                  // mutate same object: OnPush misses it
setInput(push, user); tick([def, push]);
console.log("mutated same reference     ->", def.name, def.checks, push.name, push.checks);
setInput(push, { ...user }); tick([def, push]);       // new reference
console.log("new object reference       ->", def.name, def.checks, push.name, push.checks);

// Interceptor chain: add token to API calls only, refresh once on 401.
// Time O(1) per request, space O(1).
let token = "expired", refreshes = 0, inflight = null;
const server = async (req) => {
  await null;
  if (req.url.startsWith("/api") && req.headers.Authorization !== "Bearer fresh") return { status: 401 };
  return { status: 200, url: req.url, auth: req.headers.Authorization };
};
const authInterceptor = next => async req => {
  const isApi = req.url.startsWith("/api");               // never leak the token to other hosts
  const send = () => next({ ...req, headers: isApi ? { Authorization: "Bearer " + token } : {} });
  let res = await send();
  if (res.status === 401 && isApi) {
    inflight = inflight || (async () => { refreshes++; await null; token = "fresh"; })().finally(() => (inflight = null));
    await inflight;                                        // everyone waits for the same refresh
    res = await send();
  }
  return res;
};
const http = authInterceptor(server);
(async () => {
  const rs = await Promise.all(["/api/a", "/api/b", "/api/c", "/cdn/logo.png"].map(url => http({ url })));
  console.log(JSON.stringify(rs));
  console.log("refresh calls:", refreshes);
})();

// Leak: a long-lived emitter keeps component callbacks alive. Fix: unsubscribe on destroy.
// Time O(1) per op, space O(listeners).
class Subject {
  constructor() { this.l = new Set(); }
  subscribe(fn) { this.l.add(fn); return { unsubscribe: () => this.l.delete(fn) }; }
  next(v) { this.l.forEach(f => f(v)); }
}
const clock = new Subject();                 // lives for the whole app
class Widget {
  constructor(name, fix) {
    this.name = name; this.big = new Array(1000).fill(name);
    this.sub = clock.subscribe(v => { this.last = v; });  // closure holds `this`
    this.fix = fix;
  }
  destroy() { if (this.fix) this.sub.unsubscribe(); }     // like takeUntilDestroyed
}
const leaky = new Widget("leaky", false), clean = new Widget("clean", true);
console.log("listeners while alive:", clock.l.size);
leaky.destroy(); clean.destroy();
